Create database Trabalho;
use Trabalho;
-- Dataset Portuário Sintético (2019–2025)
-- Gera tabelas e carrega dados com INSERTs em lote
SET FOREIGN_KEY_CHECKS=0;
SET UNIQUE_CHECKS=0;
SET AUTOCOMMIT=0;
START TRANSACTION;
-- Modelo Físico 
-- Notas:
-- - Tipos DECIMAL para valores monetários e pesos
-- - PKs e FKs com NOT NULL
-- - Tabela ponte reparacoes_barco com PK composta
-- - Índices para todas as FKs
-- - Checks simples para status/tipoviagem e consistência de origem/destino

-- Limpeza (opcional, para facilitar reexecução em aula)
DROP TABLE IF EXISTS reparacoes_barco;
DROP TABLE IF EXISTS taxas;
DROP TABLE IF EXISTS reparacoes;
DROP TABLE IF EXISTS contentores;
DROP TABLE IF EXISTS viagem;
DROP TABLE IF EXISTS condutor;
DROP TABLE IF EXISTS barco;
DROP TABLE IF EXISTS empresadonacontentor;
DROP TABLE IF EXISTS empresabarco;
DROP TABLE IF EXISTS localizacao;

CREATE TABLE empresabarco (
  idempresabarco      INT NOT NULL,
  nomeempresabarco    VARCHAR(200) NOT NULL,
  paisempresabarco    VARCHAR(512),
  emailempresabarco   VARCHAR(100),
  CONSTRAINT PK_empresabarco PRIMARY KEY (idempresabarco)
);

CREATE TABLE empresadonacontentor (
  idempresa     INT NOT NULL,
  nomeempresa   VARCHAR(512) NOT NULL,
  pais          VARCHAR(100),
  cidade        VARCHAR(100),
  CONSTRAINT PK_empresadonacontentor PRIMARY KEY (idempresa)
);

CREATE TABLE localizacao (
  idlocalizacao INT NOT NULL,
  cidade        VARCHAR(100) NOT NULL,
  pais          VARCHAR(100) NOT NULL,
  CONSTRAINT PK_localizacao PRIMARY KEY (idlocalizacao)
);

CREATE TABLE barco (
  idbarco                     INT NOT NULL,
  nomebarco                   VARCHAR(100) NOT NULL,
  tamanhobarco                DECIMAL(10,2),
  paisbarco                   VARCHAR(100),
  tipobarco                   VARCHAR(50),
  capacidadeteu               INT,
  empresabarco_idempresabarco INT NOT NULL,
  CONSTRAINT PK_barco PRIMARY KEY (idbarco),
  CONSTRAINT FK_barco_empresa FOREIGN KEY (empresabarco_idempresabarco)
    REFERENCES empresabarco(idempresabarco)
);

CREATE TABLE condutor (
  idcondutor     INT NOT NULL,
  idadecondutor  INT,
  nomecondutor   VARCHAR(100) NOT NULL,
  certificacao   VARCHAR(100),
  CONSTRAINT PK_condutor PRIMARY KEY (idcondutor)
);

CREATE TABLE viagem (
  idviagem                   INT NOT NULL,
  datapartida                DATE NOT NULL,
  datachegada                DATE,
  status                     VARCHAR(30) NOT NULL,
  tipoviagem                 VARCHAR(30) NOT NULL,
  localizacao_idlocalizacao  INT NOT NULL,
  localizacao_idlocalizacao1 INT NOT NULL,
  barco_idbarco              INT NOT NULL,
  condutor_idcondutor        INT NOT NULL,
  CONSTRAINT PK_viagem PRIMARY KEY (idviagem),
  CONSTRAINT FK_viagem_origem  FOREIGN KEY (localizacao_idlocalizacao)
    REFERENCES localizacao(idlocalizacao),
  CONSTRAINT FK_viagem_destino FOREIGN KEY (localizacao_idlocalizacao1)
    REFERENCES localizacao(idlocalizacao),
  CONSTRAINT FK_viagem_barco FOREIGN KEY (barco_idbarco)
    REFERENCES barco(idbarco),
  CONSTRAINT FK_viagem_condutor FOREIGN KEY (condutor_idcondutor)
    REFERENCES condutor(idcondutor),
  CONSTRAINT CK_viagem_status CHECK (status IN ('planeada','em_curso','concluida','cancelada')),
  CONSTRAINT CK_viagem_tipoviagem CHECK (tipoviagem IN ('carga','passageiros','mista','servico','outro')),
  CONSTRAINT CK_viagem_origem_destino CHECK (localizacao_idlocalizacao <> localizacao_idlocalizacao1)
);

CREATE TABLE contentores (
  idcontentor                 INT NOT NULL,
  pesocontentor               DECIMAL(12,3),
  tipomaterial                VARCHAR(100),
  tamanho                     VARCHAR(10),
  empresaoperadora            VARCHAR(100),
  empresadonacontentor_idempresa INT NOT NULL,
  viagem_idviagem             INT NOT NULL,
  CONSTRAINT PK_contentores PRIMARY KEY (idcontentor),
  CONSTRAINT FK_cont_empresa FOREIGN KEY (empresadonacontentor_idempresa)
    REFERENCES empresadonacontentor(idempresa),
  CONSTRAINT FK_cont_viagem FOREIGN KEY (viagem_idviagem)
    REFERENCES viagem(idviagem)
);

CREATE TABLE reparacoes (
  idreperacao INT NOT NULL,
  data        DATE NOT NULL,
  valor       DECIMAL(12,2) NOT NULL,
  obs         VARCHAR(512),
  CONSTRAINT PK_reparacoes PRIMARY KEY (idreperacao),
  CONSTRAINT CK_reparacoes_valor CHECK (valor >= 0)
);

CREATE TABLE taxas (
  idtaxa           INT NOT NULL,
  tipotaxa         VARCHAR(50) NOT NULL,
  valor            DECIMAL(12,2) NOT NULL,
  viagem_idviagem  INT NOT NULL,
  CONSTRAINT PK_taxas PRIMARY KEY (idtaxa),
  CONSTRAINT FK_taxa_viagem FOREIGN KEY (viagem_idviagem)
    REFERENCES viagem(idviagem),
  CONSTRAINT CK_taxa_valor CHECK (valor >= 0)
);

CREATE TABLE reparacoes_barco (
  reparacoes_idreperacao INT NOT NULL,
  barco_idbarco          INT NOT NULL,
  CONSTRAINT PK_reparacoes_barco PRIMARY KEY (reparacoes_idreperacao, barco_idbarco),
  CONSTRAINT FK_rb_rep FOREIGN KEY (reparacoes_idreperacao) REFERENCES reparacoes(idreperacao),
  CONSTRAINT FK_rb_barco FOREIGN KEY (barco_idbarco) REFERENCES barco(idbarco)
);

-- Índices de apoio (todos os FKs)
CREATE INDEX IX_barco_empresa ON barco(empresabarco_idempresabarco);-- Dados para
CREATE INDEX IX_viagem_origem ON viagem(localizacao_idlocalizacao);
CREATE INDEX IX_viagem_destino ON viagem(localizacao_idlocalizacao1);
CREATE INDEX IX_viagem_barco ON viagem(barco_idbarco);
CREATE INDEX IX_viagem_condutor ON viagem(condutor_idcondutor);
CREATE INDEX IX_cont_empresa ON contentores(empresadonacontentor_idempresa);
CREATE INDEX IX_cont_viagem ON contentores(viagem_idviagem);
CREATE INDEX IX_taxa_viagem ON taxas(viagem_idviagem);

